const views=[...document.querySelectorAll('.view')];const nav=[...document.querySelectorAll('.bottom-nav button')];const sheet=document.querySelector('#sheet');const shade=document.querySelector('#shade');const roomTitle=document.querySelector('#sheetRoom');const startCopy=document.querySelector('#sheetStart');function show(id){views.forEach(v=>v.classList.toggle('active',v.id===id));nav.forEach(b=>b.classList.toggle('active',b.dataset.view===id));window.scrollTo({top:0,behavior:'smooth'})}nav.forEach(b=>b.addEventListener('click',()=>show(b.dataset.view)));function openSheet(room,time='Starting now'){roomTitle.textContent=room;startCopy.textContent=time;sheet.classList.add('open');shade.classList.add('on')}function closeSheet(){sheet.classList.remove('open');shade.classList.remove('on')}document.querySelectorAll('.reserve').forEach(btn=>btn.addEventListener('click',()=>{const card=btn.closest('.story');openSheet(btn.dataset.room||card?.dataset.room||card?.querySelector('h3')?.textContent||'Room',btn.dataset.time?`Starting ${btn.dataset.time}`:'Starting now')}));document.querySelector('#closeSheet').addEventListener('click',closeSheet);shade.addEventListener('click',closeSheet);document.querySelectorAll('.choices button').forEach(btn=>btn.addEventListener('click',()=>{btn.parentElement.querySelectorAll('button').forEach(b=>b.classList.remove('active'));btn.classList.add('active')}));document.addEventListener('keydown',e=>{if(e.key==='Escape')closeSheet()});